-- Feedback: scenes were too dark. Every mood gets its own bright, colourful palette.
update public.personalities set image_prompt = 'Dress the pet in a pearl necklace, a hot-pink faux-fur stole and heart-shaped sunglasses. Place it on a bright pink carpet in front of a pastel pink wall with gold confetti falling and colourful balloons.' where id in ('pt-diva', 'en-diva');
update public.personalities set image_prompt = 'Tie a white napkin around the pet''s neck and add a red bow tie. Seat it in a colourful retro diner booth in turquoise and cherry red, with a burger, fries and a milkshake on the table.' where id in ('pt-esfomeado', 'en-esfomeado');
update public.personalities set image_prompt = 'Dress the pet in a chic red winter hat with a pom-pom, a mustard-yellow wool coat and a striped scarf. Place it on a snowy street lined with colourful pastel houses in bright daylight, a few snowflakes falling.' where id in ('pt-dramatico', 'en-dramatico');
update public.personalities set image_prompt = 'Dress the pet in a bright purple cape with a high collar and a monocle. Seat it on a lime-green velvet throne in a playful cartoon-villain room with purple walls and neon lights, a glass standing on the edge of a side table.' where id in ('pt-vilao', 'en-vilao');
update public.personalities set image_prompt = 'Dress the pet in sunny yellow silk pajamas with a sleep mask pushed up on its forehead. Place it in a bed full of colourful pillows in a sky-blue bedroom flooded with morning sun, a breakfast tray beside it.' where id in ('pt-preguicoso', 'en-preguicoso');
update public.personalities set image_prompt = 'Dress the pet in a bright yellow trench coat, a red fedora hat and dark sunglasses. Seat it at a sunny café terrace with colourful chairs and flowers, peeking over a blank newspaper with a suspicious side-eye, a smartphone on the table.' where id in ('pt-ciumento', 'en-ciumento');
update public.personalities set image_prompt = 'Give the pet a rainbow party hat, a loose bow tie and funny star-shaped sunglasses. Place it in a bright living room after a wild party: rainbow confetti, colourful balloons and streamers, tipped-over cups and a knocked-over plant.' where id in ('pt-caotico', 'en-caotico');
update public.personalities set image_prompt = 'Dress the pet in a black beret, a colourful silk scarf and small round glasses. Seat it at a sunny seaside restaurant terrace with an orange tablecloth, turquoise sea behind, a tiny gourmet dish and a notebook. No readable text.' where id in ('pt-critico', 'en-critico');
